tool.command:
## NFS root_squash: root in container → nobody on NFS, can't write to galaxy-owned workdir. groupadd -g 1001 gxgroup 2>/dev/null || true && useradd -M -u 1001 -g 1001 gxuser 2>/dev/null || true && export MPLCONFIGDIR=/tmp && export HOME=\$PWD && runuser -u gxuser -- bash -c "mkdir -p ./home ./home/output ./home/input" && #for $i,$filename in enumerate($infiles): runuser -u gxuser -- bash -c "ln -s '$filename' './home/input/${filename.element_identifier}.${filename.ext}'" && #end for #if str($input_type.existing) == "existing": runuser -u gxuser -- bash -c "cp '${input_type.pipeline_file}' \$HOME/home/output/'$input_type.pipeline_file.element_identifier'.cppipe" && printf '%s
' "cellprofiler -r --pipeline \$HOME/home/output/'$input_type.pipeline_file.element_identifier'.cppipe -i \$HOME/home/input -o \$HOME/home/output" > /bin/cellprofiler_galaxy && chmod +x /bin/cellprofiler_galaxy && #end if ## /init calls mktemp; Galaxy sets TMPDIR=$CWD/tmp/ which root_squash blocks. Reset to /tmp. export TMPDIR=/tmp && ## Reconfigure container nginx for path-based proxy: EP_PATH_CLEAN="\${EP_PATH%/}" && sed -i "s|location /websockify {|location \${EP_PATH_CLEAN}/websockify {
 websockify_pass unix:/tmp/vnc.sock;
 websockify_read_timeout 5d;
 websockify_send_timeout 5d;
 }

 location \${EP_PATH_CLEAN} {
 alias /opt/noVNC/;
 index index.html;
 add_header Cache-Control no-cache;
 }

 location /websockify {|" /opt/base/etc/nginx/default_site.conf && /init
